                    FfiConverterString.INSTANCE.Read(stream));
            default:
                throw new InternalException(String.Format("invalid error value '{0}' in FfiConverterTypeCairnError.Read()", value));
        }
    }

    public override int AllocationSize(CairnException value) {
        switch (value) {

            case CairnException.Message variant_value:
